#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc > 13) return 1;
    size_t n = (size_t)(argc - 1);
    uint32_t xs[12];
    for (size_t i = 0; i < n; i++) {
        char *end = NULL;
        errno = 0;
        unsigned long long value = strtoull(argv[i + 1], &end, 10);
        if (errno != 0 || end == argv[i + 1] || *end != '\0' ||
            value > UINT32_MAX) return 1;
        xs[i] = (uint32_t)value;
    }
    uint32_t acc = 0x22550819u;
    {
        uint32_t stage_0_rotate = 0x0000000Eu;
        for (size_t i = 0; i < n; i++) {
            xs[i] = (xs[i] << stage_0_rotate) | (xs[i] >> (32u - stage_0_rotate));
        }
    }
    {
        for (size_t i = 0; i < n; i++) {
            acc ^= xs[i];
        }
    }
    uint32_t final_a = 0x00000004u;
    uint32_t final_b = 0x00000009u;
    uint32_t final_multiplier = 0xDA2D15E9u;
    acc ^= acc >> final_a;
    acc *= final_multiplier;
    acc ^= acc >> final_b;
    printf("%" PRIu32 "\n", acc);
    return 0;
}
