MAGIC = b"\x1a\x7f\xd6\xdbN"


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray, memoryview)):
        return None
    data = bytes(data)
    pos = 0

    def take(n):
        nonlocal pos
        if pos + n > len(data):
            return None
        out = data[pos:pos + n]
        pos += n
        return out

    def text():
        raw = take(1)
        if raw is None:
            return None
        raw = take(raw[0])
        if raw is None or any(c < 0x20 or c > 0x7e for c in raw):
            return None
        return raw.decode("ascii")

    if take(5) != MAGIC:
        return None
    count = take(1)
    if count is None or take(1) != b"\x00":
        return None
    balance = text()
    if balance is None:
        return None

    records = []
    for _ in range(count[0]):
        temperature = text()
        created_at = take(2)
        owner = take(2)
        flags = text()
        if temperature is None or created_at is None or owner is None or flags is None:
            return None
        records.append({
            "created_at": int.from_bytes(created_at, "big"),
            "flags": flags,
            "owner": int.from_bytes(owner, "little"),
            "temperature": temperature,
        })

    if pos != len(data):
        return None
    return {"header": {"balance": balance}, "records": records}
