    pos = 11
    end = len(data)

    def text():
        nonlocal pos
        if pos >= end:
            return None
        size = data[pos]
        pos += 1
        if pos + size > end:
            return None
        raw = data[pos:pos + size]
        pos += size
        if any(byte < 0x20 or byte > 0x7E for byte in raw):
            return None
        return raw.decode("ascii")

    records = []
    for _ in range(count):
        price_cents = text()
        priority = text()
        length = text()
        if price_cents is None or priority is None or length is None:
            return None
        records.append({
            "length": length,
            "price_cents": price_cents,
            "priority": priority,
        })
    if pos != end:
        return None
    return {"header": {"zone": zone}, "records": records}
