MAGIC = b'\x91\xe1\x73\x1f\x3a'


def parse(data: bytes) -> dict | None:
    if not isinstance(data, (bytes, bytearray)) or len(data) < 8:
        return None
    data = bytes(data)
    if data[:5] != MAGIC or data[6] != 0:
        return None
    count = data[5]
    if count > 8:
        return None
    sku = data[7]
    pos = 8
    records = []
    for _ in range(count):
        if pos >= len(data):
            return None
        end = pos + 1 + data[pos]
        if end + 2 > len(data):
            return None
        raw = data[pos + 1:end]
        if any(byte < 0x20 or byte > 0x7e for byte in raw):
            return None
        priority = raw.decode('ascii')
        code = int.from_bytes(data[end:end + 2], 'big')
        pos = end + 2
        records.append({'code': code, 'priority': priority})
    if pos != len(data):
        return None
    return {'header': {'sku': sku}, 'records': records}
